<div class="background"><div class="restart" @click="restart()"></div><div class="start-block" v-if="isShowStart" :style="getStartBlock()">fight</div><myBlock class="my-block" :style="getMyBlockStyle()" :myCardsList="myHandCardList" :bloodNum="myBlood" @myUseCards="myUseCards" @enMyTurn="enMyTurn"></myBlock><div class="other-block" v-for="(otherBlock,index) in otherBlockList" :style="getOtherBlockStyle(otherBlock)" :key="index"><div class="other"><div class="other-card-name">{{getOtherCardsName(index)}}</div><div class="other-card-num">{{getOtherCardsNum(index)}}</div><div class="other-card-life-block" :style="getOtherCardsLifeStyle(index)"></div><div class="other-card-life">{{getOtherCardsLife(index)}}</div></div></div><div class="watch-back" v-if="isShowWatchBack" :style="getWatchBack()"></div><newPlayTips class="newplayer-block" :isShowFirst="isShowFirst" :isShowWatchBackStyle="isShowWatchBackStyle" @finishTip="closeNewPlayBlock"></newPlayTips><div class="other-word-text-block" v-if="isShowOtherWords" :style="getOtherWordBlockStyle()"><div class="other-word-text-block1"><div class="other-word-text">{{otherWordText}}</div></div></div><div class="other-word-name" v-if="isShowOtherWords" :style="getOtherWordBlockStyle()">{{otherWordName}}</div><div class="turn-change-block" v-if="isShowTurnChange" :style="getTurnChangeStyle()"><div class="turn-change"><div class="turn-change-left-h"></div><div class="turn-change-left-v"></div><div class="turn-change-right-h"></div><div class="turn-change-right-v"></div><div class="turn-change-text">{{playerDoing}}的回合</div></div></div><div class="turn-change-block" v-if="isShowTurnEnd" :style="getTurnEndStyle()"><div class="turn-change"><div class="turn-change-left-h"></div><div class="turn-change-left-v"></div><div class="turn-change-right-h"></div><div class="turn-change-right-v"></div><div class="turn-change-text">{{playerDoing}}的回合结束</div></div></div><animation class="animation-block" v-if="isShowAnimation" :showText="isShowAnimationText" :killName="killName" :killedName="killedName"></animation><biggerAnimation class="animation-block" v-if="isShowBiggerAnimation" :userName="biggerName" :showText="biggerText"></biggerAnimation><biggerAnimationNumberVue class="animation-block" v-if="isShowBiggerAnimationNumber" :userName="biggerNumberName" :showText="biggerAnimationNumber"></biggerAnimationNumberVue><div class="sure-buttons-block" v-if="isShowSureButton" :style="getSureButtonsBlockStyle()"><div class="sure-buttons-sure" :style="getSureButtonsStyle()" @click="choiceSureClick()">确认</div><div class="sure-buttons-cancel" @click="cancelSureButtons()">取消</div></div><div class="choice-block" v-if="isShowChoiceBlock" :style="getChoiceBlockStyle()"><div class="choice-player-block" v-if="choiceMes.type=='player'"><div class="choice-player" v-for="player in choiceMes.list" @click="choicePlayer(player)" :style="getChoiceListStyle(player)"><div class="choice-player-name">{{player.name}}</div></div></div><div class="choice-card-block" v-if="choiceMes.type=='card'"><div class="choice-card" v-for="card in choiceMes.list" @click="choiceCardFormOther(card)" :style="getChoiceListStyle(card)"><div class="choice-card-name" v-if="isShowChoiceName()">{{card.name}}</div><div class="choice-card-attribute" v-if="isShowChoiceName()" :style="getAttributeStyle(card.attribute)"></div></div></div></div><div class="settle-block" v-if="isShowSettle" :style="getSettleStyle()"><div class="settle" v-for="settle in settlementList"><div class="settle-user">{{settle.user}}</div><div class="settle-card">{{settle.card}}</div></div></div></div>